package ru.neverland.townysieges;

import java.io.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.CompletionStage;

/** Bank intent and exact repair targets persist before payment; applied blocks are never charged again. */
public final class RaidRepairsStore {
    public record Cell(RepairPlans.Cell block,String version,double remaining,double maximum,boolean missing){}
    public record Job(UUID id,UUID town,UUID actor,String project,String title,String fingerprint,int level,long levelPrice,
                      double maximum,double lost,long cents,long before,long created,String state,String note,List<Cell> cells,String protocol){
        public Job { cells=List.copyOf(cells);if(!Set.of("LEGACY","TREASURY_V1").contains(protocol))throw new IllegalArgumentException("Неизвестный протокол оплаты ремонта"); }
        public Job(UUID id,UUID town,UUID actor,String project,String title,String fingerprint,int level,long levelPrice,double maximum,double lost,long cents,long before,long created,String state,String note,List<Cell> cells){this(id,town,actor,project,title,fingerprint,level,levelPrice,maximum,lost,cents,before,created,state,note,cells,"LEGACY");}
        public boolean treasury(){return protocol.equals("TREASURY_V1");}
    }
    private final RaidStore storage;
    public RaidRepairsStore(RaidStore storage){this.storage=storage;}
    static void initialize(Connection db)throws SQLException{try(var s=db.createStatement()){
        s.execute("CREATE TABLE IF NOT EXISTS building_repairs(id TEXT PRIMARY KEY,town TEXT NOT NULL,project TEXT NOT NULL,actor TEXT NOT NULL,title TEXT NOT NULL,fingerprint TEXT NOT NULL,level INTEGER NOT NULL,level_price INTEGER NOT NULL,maximum REAL NOT NULL,lost REAL NOT NULL,cents INTEGER NOT NULL,balance_before INTEGER NOT NULL,created INTEGER NOT NULL,state TEXT NOT NULL,note TEXT NOT NULL,cells BLOB NOT NULL)");
        boolean protocol=false;try(var columns=s.executeQuery("PRAGMA table_info(building_repairs)")){while(columns.next())if(columns.getString("name").equals("payment_protocol"))protocol=true;}
        if(!protocol)s.execute("ALTER TABLE building_repairs ADD COLUMN payment_protocol TEXT NOT NULL DEFAULT 'LEGACY'");
        s.execute("CREATE UNIQUE INDEX IF NOT EXISTS building_repair_pending ON building_repairs(town,project) WHERE state NOT IN ('DONE','CANCELLED')");
        s.execute("CREATE TABLE IF NOT EXISTS building_repair_steps(job TEXT NOT NULL,key TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(job,key))");
        s.execute("UPDATE building_repairs SET state='REVIEW_BANK',note='Сервер остановился во время списания; нужна сверка' WHERE state='PAYING' AND payment_protocol='LEGACY'");
    }}
    private Connection db(){return storage.connection();}
    static byte[] encode(List<Cell> cells)throws IOException{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeInt(cells.size());for(var c:cells){var k=c.block().key();out.writeUTF(k.world().toString());out.writeInt(k.x());out.writeInt(k.y());out.writeInt(k.z());out.writeUTF(c.block().material());out.writeUTF(c.block().data());out.writeUTF(c.block().top());out.writeUTF(c.version());out.writeDouble(c.remaining());out.writeDouble(c.maximum());out.writeBoolean(c.missing());}}return bytes.toByteArray();}
    static List<Cell> decode(byte[] bytes)throws IOException{var out=new ArrayList<Cell>();try(var in=new DataInputStream(new ByteArrayInputStream(bytes))){int n=in.readInt();if(n<0||n>100000)throw new IOException("Повреждена квитанция ремонта");for(int i=0;i<n;i++)out.add(new Cell(new RepairPlans.Cell(new RaidStore.Key(UUID.fromString(in.readUTF()),in.readInt(),in.readInt(),in.readInt()),in.readUTF(),in.readUTF(),in.readUTF()),in.readUTF(),in.readDouble(),in.readDouble(),in.readBoolean()));if(in.available()!=0)throw new IOException("Лишние данные квитанции ремонта");}return List.copyOf(out);}
    private Job row(ResultSet r)throws Exception{return new Job(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("town")),UUID.fromString(r.getString("actor")),r.getString("project"),r.getString("title"),r.getString("fingerprint"),r.getInt("level"),r.getLong("level_price"),r.getDouble("maximum"),r.getDouble("lost"),r.getLong("cents"),r.getLong("balance_before"),r.getLong("created"),r.getString("state"),r.getString("note"),decode(r.getBytes("cells")),r.getString("payment_protocol"));}
    private Job read(UUID id)throws Exception{try(var p=db().prepareStatement("SELECT * FROM building_repairs WHERE id=?")){p.setString(1,id.toString());try(var r=p.executeQuery()){return r.next()?row(r):null;}}}
    public CompletionStage<Job> get(UUID id){return storage.submit(()->read(id));}
    public CompletionStage<List<Job>> list(boolean pending){return storage.submit(()->{var out=new ArrayList<Job>();try(var s=db().createStatement();var r=s.executeQuery("SELECT * FROM building_repairs "+(pending?"WHERE state NOT IN ('DONE','CANCELLED') ORDER BY CASE WHEN state IN ('PAID','PAYING') THEN 0 ELSE 1 END,created ASC":"ORDER BY created DESC")+" LIMIT 100")){while(r.next())out.add(row(r));}return List.copyOf(out);});}
    public CompletionStage<Job> create(UUID actor,RepairPlans.Plan plan,double total,double lost,long cents,long before,List<Cell> cells){return create(actor,plan,total,lost,cents,before,cells,false);}
    public CompletionStage<Job> create(UUID actor,RepairPlans.Plan plan,double total,double lost,long cents,long before,List<Cell> cells,boolean treasury){return storage.repairMutation(()->storage.transaction(()->{
        if(cents!=RepairRules.cost(plan.price(),lost,total)||cells.isEmpty())throw new IllegalArgumentException("Условия ремонта изменились");
        try(var p=db().prepareStatement("SELECT id FROM building_repairs WHERE town=? AND project=? AND state NOT IN ('DONE','CANCELLED')")){p.setString(1,plan.town().toString());p.setString(2,plan.project());try(var r=p.executeQuery()){if(r.next())throw new IllegalArgumentException("Предыдущий ремонт уже сохранён: "+r.getString(1));}}
        for(var c:cells){var d=BuildingDamageStore.read(db(),c.block().key().id());if(!matches(d,plan.town(),plan.project(),c))throw new IllegalArgumentException("Повреждения изменились. Откройте ремонт заново");}
        UUID id=UUID.randomUUID();try(var p=db().prepareStatement("INSERT INTO building_repairs(id,town,project,actor,title,fingerprint,level,level_price,maximum,lost,cents,balance_before,created,state,note,cells,payment_protocol) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")){p.setString(1,id.toString());p.setString(2,plan.town().toString());p.setString(3,plan.project());p.setString(4,actor.toString());p.setString(5,plan.title());p.setString(6,plan.fingerprint());p.setInt(7,plan.level());p.setLong(8,plan.price());p.setDouble(9,total);p.setDouble(10,lost);p.setLong(11,cents);p.setLong(12,before);p.setLong(13,System.currentTimeMillis());p.setString(14,cents==0?"PAID":treasury?"TREASURY_PENDING":"PAYING");p.setString(15,"");p.setBytes(16,encode(cells));p.setString(17,treasury?"TREASURY_V1":"LEGACY");p.executeUpdate();}
        try(var p=db().prepareStatement("INSERT INTO building_repair_steps VALUES(?,?,'PENDING')")){for(var c:cells){p.setString(1,id.toString());p.setString(2,c.block().key().id());p.addBatch();}p.executeBatch();}return read(id);
    })).thenCompose(job->storage.submit(()->{try(var statement=db().createStatement()){statement.execute("PRAGMA wal_checkpoint(FULL)");}return read(job.id());}));}
    static boolean matches(BuildingDamageStore.Damage d,UUID town,String project,Cell c){return d!=null&&d.town().equals(town)&&d.project().equals(project)&&d.material().equals(c.block().material())&&d.version().equals(c.version())&&d.remaining()==c.remaining()&&d.maximum()==c.maximum()&&d.pending().isEmpty();}
    public CompletionStage<Job> change(UUID id,String expected,String next,String note){return storage.repairMutation(()->{try(var p=db().prepareStatement("UPDATE building_repairs SET state=?,note=? WHERE id=? AND state=?")){p.setString(1,next);p.setString(2,note);p.setString(3,id.toString());p.setString(4,expected);if(p.executeUpdate()!=1)throw new IllegalArgumentException("Состояние ремонта изменилось");}return read(id);});}
    /** Stale funding callbacks may observe a repair already being applied. They cannot rewind it. */
    public CompletionStage<Job> funding(UUID id,RepairTreasury.Outcome outcome){return storage.repairMutation(()->storage.transaction(()->{
        var job=read(id);if(job==null||!job.treasury())throw new IllegalArgumentException("Нет новой квитанции оплаты ремонта");
        if(!Set.of("TREASURY_PENDING","TREASURY_REVIEW").contains(job.state())||outcome==RepairTreasury.Outcome.WAITING)return job;
        String next=switch(outcome){case PAID->"PAID";case REJECTED->"CANCELLED";case REVIEW->"TREASURY_REVIEW";default->throw new IllegalArgumentException("Нет результата казны");};
        String note=switch(outcome){case PAID->"Списание подтверждено сохранённой квитанцией казны";case REJECTED->"Казна отклонила оплату; деньги не списаны";default->"Нужна сверка операции в казне: "+id;};
        try(var p=db().prepareStatement("UPDATE building_repairs SET state=?,note=? WHERE id=?")){p.setString(1,next);p.setString(2,note);p.setString(3,id.toString());p.executeUpdate();}return read(id);
    }));}
    public CompletionStage<Map<String,String>> steps(UUID id){return storage.submit(()->{var out=new HashMap<String,String>();try(var p=db().prepareStatement("SELECT key,state FROM building_repair_steps WHERE job=?")){p.setString(1,id.toString());try(var r=p.executeQuery()){while(r.next())out.put(r.getString(1),r.getString(2));}}return Map.copyOf(out);});}
    public CompletionStage<Void> begin(UUID id,List<Cell> cells){return storage.repairMutation(()->storage.transaction(()->{var job=read(id);if(job==null||!job.state().equals("PAID"))throw new IllegalArgumentException("Ремонт не оплачен");for(var c:cells){if(!matches(BuildingDamageStore.read(db(),c.block().key().id()),job.town(),job.project(),c))throw new IllegalArgumentException("Повреждения изменились после оплаты; нужна проверка");try(var p=db().prepareStatement("UPDATE building_repair_steps SET state='APPLYING' WHERE job=? AND key=? AND state='PENDING'")){p.setString(1,id.toString());p.setString(2,c.block().key().id());p.executeUpdate();}}return null;}));}
    public CompletionStage<Void> applied(UUID id,List<Cell> cells){return storage.repairMutation(()->storage.transaction(()->{var job=read(id);for(var c:cells){var k=c.block().key().id();var d=BuildingDamageStore.read(db(),k);if(d!=null&&!matches(d,job.town(),job.project(),c))throw new IllegalArgumentException("Повреждения изменились при завершении ремонта");BuildingDamageStore.reset(db(),k);try(var p=db().prepareStatement("DELETE FROM hp WHERE key=?")){p.setString(1,k);p.executeUpdate();}try(var p=db().prepareStatement("UPDATE building_repair_steps SET state='DONE' WHERE job=? AND key=?")){p.setString(1,id.toString());p.setString(2,k);p.executeUpdate();}}return null;}));}
    public CompletionStage<Job> resolve(UUID id,String decision,String actor,String reason){return storage.repairMutation(()->storage.transaction(()->{if(reason==null||reason.strip().length()<8||reason.length()>200)throw new IllegalArgumentException("Укажите основание: 8–200 символов");var job=read(id);if(job==null)throw new IllegalArgumentException("Квитанция не найдена");String next;if(!job.treasury()&&job.state().equals("REVIEW_BANK")&&decision.equals("paid"))next="PAID";else if(!job.treasury()&&job.state().equals("REVIEW_BANK")&&decision.equals("retry"))next="CANCELLED";else if(job.state().equals("REVIEW_WORLD")&&decision.equals("resume")){next="PAID";try(var p=db().prepareStatement("UPDATE building_repair_steps SET state='PENDING' WHERE job=? AND state='APPLYING'")){p.setString(1,id.toString());p.executeUpdate();}}else if(job.state().equals("REVIEW_WORLD")&&decision.equals("complete")){next="DONE";for(var c:job.cells()){var d=BuildingDamageStore.read(db(),c.block().key().id());if(matches(d,job.town(),job.project(),c)){BuildingDamageStore.reset(db(),c.block().key().id());try(var p=db().prepareStatement("DELETE FROM hp WHERE key=?")){p.setString(1,c.block().key().id());p.executeUpdate();}}}try(var p=db().prepareStatement("UPDATE building_repair_steps SET state='DONE' WHERE job=?")){p.setString(1,id.toString());p.executeUpdate();}}else throw new IllegalArgumentException("Решение не подходит к состоянию ремонта");try(var p=db().prepareStatement("UPDATE building_repairs SET state=?,note=? WHERE id=?")){p.setString(1,next);p.setString(2,actor+": "+reason);p.setString(3,id.toString());p.executeUpdate();}return read(id);}));}
}
